<script setup lang="ts">
import { onMounted, ref } from 'vue';import { createTicket,listFindings,listTickets } from '@/api/client';import DataState from '@/components/DataState.vue'
const findings=ref<Array<Record<string,unknown>>>([]);const tickets=ref<Array<Record<string,unknown>>>([]);const error=ref(false)
async function load(){error.value=false;try{const [f,t]=await Promise.all([listFindings(),listTickets()]);findings.value=f.items;tickets.value=t.items}catch{error.value=true}}
async function ticket(id:string){await createTicket(id);await load()}onMounted(load)
</script>
<template><div class="page two-column"><section class="panel"><header><div><p class="kicker">ANOMALY QUEUE</p><h2>异常归因</h2></div></header><DataState v-if="error" error title="异常数据不可用" detail="恢复服务后重试。" @retry="load"/><DataState v-else-if="findings.length===0" title="暂无开放异常" detail="异常检测结果会按租户显示。"/><article v-for="f in findings" v-else :key="String(f.finding_id)" class="finding"><div><strong>{{f.kind}}</strong><p>{{f.detail}}</p><span class="badge" :data-state="f.severity">{{f.severity}}</span></div><button class="quiet-button" @click="ticket(String(f.finding_id))">创建工单</button></article></section><section class="panel"><header><div><p class="kicker">EXTERNAL ACTIONS</p><h2>治理工单</h2></div></header><DataState v-if="tickets.length===0" title="暂无工单" detail="只有已授权异常可以创建幂等工单。"/><article v-for="t in tickets" v-else :key="String(t.ticket_id)" class="ticket"><span class="badge" :data-state="t.status">{{t.status}}</span><div><strong>{{t.ticket_id}}</strong><p>{{t.finding_id}}</p></div></article></section></div></template>
